pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint[] memory v) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == v.length);
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, 1);
            vm.assume(tos[i] != address(0));
        }
        // Set the sender to the authorized address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool result = c.transfer(tos, v);
        assertTrue(result == true);
    }
}

